import { SYSTEM_PROMPT } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- Retry Helper ---
const retryOperation = async <T>(operation: () => Promise<T>, maxRetries: number = 3): Promise<T> => {
    let lastError: any;
    for (let i = 0; i < maxRetries; i++) {
        try {
            return await operation();
        } catch (error: any) {
            lastError = error;
            const isQuotaError = error.message?.includes('429') || 
                                 error.status === 429 || 
                                 error.message?.toLowerCase().includes('quota') || 
                                 error.message?.includes('RESOURCE_EXHAUSTED');

            if (isQuotaError && i < maxRetries - 1) {
                const delay = Math.pow(2, i) * 1000 + (Math.random() * 1000); // Exponential Backoff + Jitter
                console.warn(`Gemini API Quota Hit. Retrying in ${Math.round(delay)}ms... (Attempt ${i + 1}/${maxRetries})`);
                await new Promise(resolve => setTimeout(resolve, delay));
                continue;
            }
            throw error;
        }
    }
    throw lastError;
};
